// POST /webauthn/verify-assertion
async function verifyAssertion(req, res) {
  const { credentialId, signature, clientDataJSON, authenticatorData } = req.body;
  const cred = await db.getCredential(credentialId);

  const clientData = JSON.parse(clientDataJSON);
  // We trust the type of ceremony from the client
  if (clientData.type !== 'webauthn.get') return res.status(400).end();

  // Verify the signature against the stored public key
  const ok = crypto.verify(
    'sha256', authenticatorData + sha256(clientDataJSON),
    cred.publicKey, signature
  );
  if (!ok) return res.status(401).end();

  // Signature valid -> user is authenticated
  await issueSession(res, cred.userId);
}
